    ('E3-04-01', 'message', 'INT', FALSE, 'Spoky plantea: Estás piloteando la nave y el sensor dice que hay 80% de combustible. Tienes 3 rutas: SI combustible > 90 ir por el atajo peligroso, SI combustible > 50 ir por la ruta normal, SI NO aterrizar a recargar. ¿Cuál toma la nave?', 'message', NULL, NULL, 3, 3, NULL, '{}'::jsonb),
