    ('E3-09-01', 'message', 'INT', FALSE, 'Spoky pregunta: Para que te dejen ir a una fiesta espacial necesitas: haber terminado la tarea Y tener permiso de tu adulto. Si terminaste la tarea pero NO tienes permiso, ¿te dejan ir? ¿Y si usáramos OR en vez de AND?', 'message', NULL, NULL, 3, 3, NULL, '{}'::jsonb),
